using Astrea.GameElements;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PrecisionMantraAction", menuName = "Data/Battle/Battle Actions/Sothis/PrecisionMantra Action")]
public class PrecisionMantraAction : ChooseDiceAction
{
	[Header("Precision Action")]
	[SerializeField]
	private PrecisionAction precisionAction;

	[Header("Soul Heat Requirement")]
	[SerializeField]
	private MinimumVariableSoulHeatCastAction precisionMantraLogicAction;

	[SerializeField]
	private MinimumVariableSoulHeatCastAction voidMantraLogicAction;

	public MinimumVariableSoulHeatCastAction PrecisionMantraLogicAction => precisionMantraLogicAction;

	public override void ActionSelected(int amount)
	{
		base.ActionSelected(amount);
		precisionAction.ResetVariables();
	}

	public override bool CheckConditionToBeCasted(int actionValue, bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (precisionMantraLogicAction.GetSoulHeatAmountToUse(activateFeedback: false) >= actionValue)
		{
			return precisionAction.CheckConditionToBeCasted(playerHand, diceOwnerEnum);
		}
		return true;
	}

	public override DiceActionLogic GetDiceActionLogic(int actionValue = -1)
	{
		if (precisionMantraLogicAction.GetSoulHeatAmountToUse(activateFeedback: false) >= actionValue)
		{
			return diceActionLogic;
		}
		return voidMantraLogicAction.BattleAction.GetDiceActionLogic(actionValue);
	}

	public override void CastAmount(int amount, GameObject source)
	{
		precisionMantraLogicAction.CastMultipleSoulHeatTierFirstActionSoulHeatVariableAction(delegate
		{
			precisionAction.DiceSelected(diceList[0]);
			precisionAction.Cast(source);
		}, null, null, amount, source);
	}
}
